import java.io.*;import java.nio.file.*;import java.lang.reflect.*;import org.rabochaya.projects.*;import org.rabochaya.maptests.GeoTiffFixtures;
public class StripAccess {public static void main(String[] args)throws Exception{File f=new File(args[0],"synthetic-strip.tif");Files.write(f.toPath(),GeoTiffFixtures.matrix(GeoTiffFixtures.deflated(true,4326,1,true,2,2048),GeoTiffFixtures.affine(4326,false)));int restarts=0;Object last=null;try(GeoTiffRaster r=new GeoTiffRaster(f)){Field decoder=GeoTiffRaster.class.getDeclaredField("decoder");decoder.setAccessible(true);for(int y=2047;y>=1903;y-=16){r.modelColor(2-(y+.5)*.01,.985);Object current=decoder.get(r);if(current!=last)restarts++;last=current;}}System.out.println("10 reverse affine samples: "+restarts+" distinct strip inflater streams; source has2048 rows in one strip");}}
